window.RP_SESSION={"id":"S-c1fe4e765b80","messages":[{"id":"RP-II-0103353","time":"2026-05-20T03:35:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"약속 대련은 늘 유익합니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103354","time":"2026-05-20T03:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"훈련장에서 아무리 더미 인형을 후려쳐 봐야 얻기 힘든 경험을 어느 정도는 체험할 수 있죠.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103355","time":"2026-05-20T03:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 훈련용 가검을 손에 쥐고 그 끝을 통해 친구를 바라봅니다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103356","time":"2026-05-20T03:36:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아. 주, 준비됐어! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103357","time":"2026-05-20T03:37:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"나도 준비됐어!\"\n훈련용 스태프 손에 들고 너 바라본다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103358","time":"2026-05-20T03:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 좋아. 그럼, 가, 간다! \"\n\n검을 들고 빠르게 거리를 좁히며 다가간다!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103359","time":"2026-05-20T03:38:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103360","time":"2026-05-20T03:38:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[7] + [2] = [9]\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-II-0103361","time":"2026-05-20T03:39:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마의 가검은 금새 멜리아를 향해 뻗어진다. 멜리아의 대응은?","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103362","time":"2026-05-20T03:40:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"우왓..!\"\n순식간에 푸른빛의 아름다운 새의 형상을 한 마법을 네 칼끝으로 날린다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103363","time":"2026-05-20T03:41:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"!마법","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103364","time":"2026-05-20T03:41:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'멜리아 루넬리오스'의 마법 판정 :\n[6, 4, 1]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-II-0103365","time":"2026-05-20T03:41:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103366","time":"2026-05-20T03:41:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[4, 6, 3] + [6, 6]\n성공수 : [ 4 ]","characters":[]},{"id":"RP-II-0103367","time":"2026-05-20T03:41:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"새가 가검의 끝과 부딪혀 마법이 쪼개지고 칼끝이 멜리아에게 살짝 가서 닿았다. 레마 1승!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103368","time":"2026-05-20T03:42:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 하하, 첫 판은 내가 이, 이겼네. 우리 소원권 내, 내기 할까? \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103369","time":"2026-05-20T03:42:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"아쉽네, 좋아! 이번에는 내가 이길 거라구!\"","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103370","time":"2026-05-20T03:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 다시 원래 거리로 돌아가서...","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103371","time":"2026-05-20T03:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103372","time":"2026-05-20T03:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[5] + [2] = [7]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0103373","time":"2026-05-20T03:43:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"이번에는 레마가 다가가는 박자가 느립니다. 멜리아, 대응!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103374","time":"2026-05-20T03:45:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"이번에는 꽃의 형상을 한 마법을 순식간에 레마의 칼끝으로 날립니다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103375","time":"2026-05-20T03:45:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"!마법","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103376","time":"2026-05-20T03:45:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'멜리아 루넬리오스'의 마법 판정 :\n[6, 3, 6]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-II-0103377","time":"2026-05-20T03:45:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103378","time":"2026-05-20T03:45:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[5, 4, 3] + [5, 2]\n성공수 : [ 3 ]","characters":[]},{"id":"RP-II-0103379","time":"2026-05-20T03:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"레마는 마법을 받아내서 쳐내고,","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103380","time":"2026-05-20T03:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103381","time":"2026-05-20T03:46:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 민첩 판정 :\n[4] + [2] = [6]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-II-0103382","time":"2026-05-20T03:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"마법을 받아내기에 벅찼는지 쉽사리 거리를 좁히지 못하는 레마.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103383","time":"2026-05-20T03:46:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"멜리아, 대응!","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103384","time":"2026-05-20T03:47:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"뾰족한 눈꽃 결정의 형상을 한 마법을 레마에게 날립니다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103385","time":"2026-05-20T03:48:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"!마법","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103386","time":"2026-05-20T03:48:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'멜리아 루넬리오스'의 마법 판정 :\n[3, 5, 5]\n성공수 : [ 2 ]","characters":[]},{"id":"RP-II-0103387","time":"2026-05-20T03:48:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"!격투","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103388","time":"2026-05-20T03:48:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'레마 캐롤라인'의 격투 판정 :\n[1, 3, 2] + [1, 6]\n성공수 : [ 1 ]","characters":[]},{"id":"RP-II-0103389","time":"2026-05-20T03:48:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 꺅! \"\n\n눈꽃 형상의 마법을 튕겨내지 못하고 칼을 놓친다.","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103390","time":"2026-05-20T03:49:00+09:00","room":"RP II","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"reviewed","type":"dialogue","body":"\" 멜리아가 이, 이겼어! \"\n\n레마는 멜리아가 자신을 이겼다는데 기쁨에 차서 감격하여 멜리아를 끌어안는다.\n\n\" 뭐라도 당장 내가 할 수 이, 있는거 하나 들어줄게! \"","characters":["P-fec1db60d51e"]},{"id":"RP-II-0103391","time":"2026-05-20T03:50:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"\"헤헤... 음, 그러면..! 맛있는 거 만들어줘!\"\n너한테 끌어안겨 헤실헤실 웃으며 잠시 고민하고는 소원 얘기한다.","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103392","time":"2026-05-20T03:50:00+09:00","room":"RP II","name":"멜리아 루넬리오스","profile":"멜리아 루넬리오스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-5401fadc6bc3"]},{"id":"RP-II-0103393","time":"2026-05-20T03:50:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.\n메시지가 삭제되었습니다.\n메시지가 삭제되었습니다.","characters":[]}]};
